{
  "name": "zscore_gap_weighted_bt_v2",
  "intuition": "Bradley-Terry preference loss with a cost-gap-derived adaptive weight. Uses robust key fallbacks so it works across batch/extra conventions, and keeps weights bounded for stability.",
  "pseudocode": "lp_w, lp_l = get_logprobs(batch, model_output, extra); delta = lp_w - lp_l; base = -logsigmoid(alpha*delta); gap_src = get_gap(batch, model_output, extra, default=delta); w = clamp(softplus(k*zscore(gap_src))+eps, 0, w_max); L = mean(w*base)",
  "hyperparams": {
    "alpha": 1.0,
    "k": 1.0,
    "eps": 0.1,
    "w_max": 10.0
  },
  "operators_used": [
    "logsigmoid",
    "softplus",
    "zscore",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Robustly source required tensors from batch/model_output/extra.
    def _get(*keys):
        for k in keys:
            if k is None:
                continue
            if isinstance(extra, dict) and k in extra:
                return extra[k]
            if isinstance(batch, dict) and k in batch:
                return batch[k]
            if isinstance(model_output, dict) and k in model_output:
                return model_output[k]
        return None

    log_prob_w = _get("log_prob_w", "logp_w", "chosen_logps", "logps_w")
    log_prob_l = _get("log_prob_l", "logp_l", "rejected_logps", "logps_l")

    # If only a combined log-prob tensor is provided, fall back to slicing.
    if (log_prob_w is None or log_prob_l is None):
        both = _get("log_probs", "logprobs", "logps")
        if both is not None:
            log_prob_w = both[..., 0]
            log_prob_l = both[..., 1]

    # Last resort: allow direct deltas if available.
    if (log_prob_w is None or log_prob_l is None):
        delta = _get("delta", "logit_delta", "logprob_delta")
        if delta is None:
            # Create a safe zero delta (keeps loss finite) using any available tensor.
            ref = _get("delta_z", "objective", "reward", "score")
            if ref is None:
                ref = model_output
            delta = ref * 0.0
    else:
        delta = log_prob_w - log_prob_l

    hp = extra.get("hyperparams", {}) if isinstance(extra, dict) else {}
    alpha = float(_get("alpha") if _get("alpha") is not None else hp.get("alpha", 1.0))
    k = float(_get("k") if _get("k") is not None else hp.get("k", 1.0))
    eps = float(_get("eps") if _get("eps") is not None else hp.get("eps", 0.1))
    w_max = float(_get("w_max") if _get("w_max") is not None else hp.get("w_max", 10.0))

    base = -ops.logsigmoid(alpha * delta)

    gap_src = _get("delta_z", "gap", "objective_gap", "reward_gap", "cost_gap")
    if gap_src is None:
        gap_src = delta

    gap = ops.zscore(gap_src)
    w = ops.softplus(k * gap) + eps
    w = ops.clamp(w, 0.0, w_max)

    base_weight = _get("weight", "sample_weight")
    if base_weight is not None:
        w = w * base_weight

    loss = (w * base).mean()
    return loss",
  "theoretical_basis": "Weighted Bradley-Terry / logistic preference loss. The adaptive weight is a bounded softplus of a z-scored gap signal to emphasize larger objective differences while keeping gradients stable.",
  "implementation_hint": {
    "mode": "preference",
