  "code": "def generated_loss(batch, model_output, extra):
    # Prefer standard runtime sources for log-probs; avoid requiring batch keys.
    log_prob_w = None
    log_prob_l = None

    if isinstance(model_output, dict):
        log_prob_w = model_output.get("log_prob_w", model_output.get("logp_w", None))
        log_prob_l = model_output.get("log_prob_l", model_output.get("logp_l", None))

    if log_prob_w is None and isinstance(batch, dict):
        log_prob_w = batch.get("log_prob_w", batch.get("logp_w", None))
    if log_prob_l is None and isinstance(batch, dict):
        log_prob_l = batch.get("log_prob_l", batch.get("logp_l", None))

    # Last resort: accept extra keys if provided.
    if log_prob_w is None and isinstance(extra, dict):
        log_prob_w = extra.get("log_prob_w", extra.get("logp_w", None))
    if log_prob_l is None and isinstance(extra, dict):
        log_prob_l = extra.get("log_prob_l", extra.get("logp_l", None))

    # Compute a gap signal for weighting; default to a constant if unavailable.
    delta_z = None
    if isinstance(extra, dict):
        delta_z = extra.get("delta_z", extra.get("gap", None))
    if delta_z is None and isinstance(batch, dict):
        delta_z = batch.get("delta_z", batch.get("gap", None))

    # Optional external weight multiplier.
    base_weight = None
    if isinstance(extra, dict):
        base_weight = extra.get("weight", None)
    if base_weight is None and isinstance(batch, dict):
        base_weight = batch.get("weight", None)

    # Hyperparams (prefer explicit extra values).
    hp = extra.get("hyperparams", {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get("alpha") if isinstance(extra, dict) else None) or hp.get("alpha", 1.0))
    k = float((extra.get("k") if isinstance(extra, dict) else None) or hp.get("k", 1.0))
    eps = float((extra.get("eps") if isinstance(extra, dict) else None) or hp.get("eps", 0.1))
    w_max = float((extra.get("w_max") if isinstance(extra, dict) else None) or hp.get("w_max", 10.0))
    gap_fallback = float((extra.get("gap_fallback") if isinstance(extra, dict) else None) or hp.get("gap_fallback", 0.0))

    # If log-probs are missing, return a safe zero scalar with correct type/device.
    if log_prob_w is None or log_prob_l is None:
        if log_prob_w is not None:
            return (log_prob_w * 0.0).mean()
        if log_prob_l is not None:
            return (log_prob_l * 0.0).mean()
        # If neither exists, try to anchor on any tensor in model_output/batch/extra.
        anchor = None
        if isinstance(model_output, dict):
            for v in model_output.values():
                anchor = v
                break
        if anchor is None and isinstance(batch, dict):
            for v in batch.values():
                anchor = v
                break
        if anchor is None and isinstance(extra, dict):
            for v in extra.values():
                anchor = v
                break
        if anchor is None:
            # As a final fallback, produce a python float; most runtimes wrap to tensor.
            return 0.0
        return (anchor * 0.0).mean()

    delta = log_prob_w - log_prob_l
    base = -ops.logsigmoid(alpha * delta)

    if delta_z is None:
        gap = delta * 0.0 + gap_fallback
    else:
        gap = ops.zscore(delta_z)

    w = ops.softplus(k * gap) + eps
    w = ops.clamp(w, 0.0, w_max)

    if base_weight is not None:
        w = w * base_weight

    loss = (w * base).mean()
    return loss",
