{
  "name": "m3_stable_bt_gap_weight",
  "intuition": "Stabilized Bradley-Terry preference loss. Uses a safe fallback for winner/loser log-probs, clamps extreme deltas to prevent loss blow-ups, and injects objective sensitivity via a bounded, positive multiplicative weight derived from an available objective-gap signal (delta_z / delta_rank / delta_regret / cost_a-cost_b). Keeps preference semantics unchanged because the base term stays nonnegative and only gets scaled within a small range.",
  "pseudocode": "get logp_w/logp_l from batch or model_output; delta=clamp(logp_w-logp_l,-dmax,dmax); base=-logsigmoid(alpha*delta); get objective gap g from delta_z|delta_rank|delta_regret|(cost_a-cost_b); g=clamp(g,-gmax,gmax); w=clamp(1+beta*g, wmin, wmax); return mean(w*base)",
  "hyperparams": {
    "alpha": 1.0,
    "beta": 0.02,
    "dmax": 20.0,
    "gmax": 5.0,
    "wmin": 0.5,
    "wmax": 1.5
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "mean",
    "ones_like"
  ],
  "expects": {
    "batch": [],
    "model_output": [],
    "extra": []
  },
  "code": "def generated_loss(batch, model_output, extra):
    # Robustly fetch winner/loser log-prob tensors from common key variants.
    log_prob_w = batch.get("log_prob_w", None)
    if log_prob_w is None:
        log_prob_w = batch.get("chosen_logprob", None)
    if log_prob_w is None:
        log_prob_w = model_output.get("log_prob_w", None)
    if log_prob_w is None:
        log_prob_w = model_output.get("chosen_logprob", None)

    log_prob_l = batch.get("log_prob_l", None)
    if log_prob_l is None:
        log_prob_l = batch.get("rejected_logprob", None)
    if log_prob_l is None:
        log_prob_l = model_output.get("log_prob_l", None)
    if log_prob_l is None:
        log_prob_l = model_output.get("rejected_logprob", None)

    # If still missing, return a well-defined scalar zero (avoid hard failure).
    if (log_prob_w is None) or (log_prob_l is None):
        fallback = batch.get("delta_z", None)
        if fallback is None:
            fallback = model_output.get("delta_z", None)
        if fallback is None:
            fallback = batch.get("delta_rank", None)
        if fallback is None:
            fallback = model_output.get("delta_rank", None)
        if fallback is None:
            fallback = batch.get("delta_regret", None)
        if fallback is None:
            fallback = model_output.get("delta_regret", None)
        if fallback is None:
            fallback = batch.get("cost_a", None)
        if fallback is None:
            fallback = model_output.get("cost_a", None)
        if fallback is not None:
            return (fallback * 0.0).mean()
        # Last resort: constant tensor via ones_like if any tensor exists.
        any_t = batch.get("weight", None)
        if any_t is None:
            any_t = model_output.get("weight", None)
        if any_t is not None:
            return (ops.ones_like(any_t) * 0.0).mean()
        return 0.0

    alpha = 1.0
    beta = 0.02
    dmax = 20.0
    gmax = 5.0
    wmin = 0.5
    wmax = 1.5

    # Clamp delta to avoid extreme losses/out-of-range issues.
    delta = ops.clamp(log_prob_w - log_prob_l, -dmax, dmax)
    base = -ops.logsigmoid(alpha * delta)

    # Objective gap signal (try several common keys). Prefer already-computed deltas.
    gap = batch.get("delta_z", None)
    if gap is None:
        gap = model_output.get("delta_z", None)
    if gap is None:
        gap = batch.get("delta_rank", None)
    if gap is None:
        gap = model_output.get("delta_rank", None)
    if gap is None:
        gap = batch.get("delta_regret", None)
    if gap is None:
        gap = model_output.get("delta_regret", None)

    # Fallback to cost difference if present.
    if gap is None:
        cost_a = batch.get("cost_a", None)
        if cost_a is None:
            cost_a = model_output.get("cost_a", None)
        cost_b = batch.get("cost_b", None)
        if cost_b is None:
            cost_b = model_output.get("cost_b", None)
        if (cost_a is not None) and (cost_b is not None):
            gap = cost_a - cost_b

    # Bounded multiplicative weight; preserves preference semantics.
